CREATE OR REPLACE FUNCTION public.test_pe_branches() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p uuid:=gen_random_uuid(); p2 uuid:=gen_random_uuid(); c uuid:=gen_random_uuid(); client uuid:=gen_random_uuid(); bank uuid:=gen_random_uuid(); e uuid; e2 uuid; r jsonb; b uuid; tx uuid; inv uuid; cr uuid; ia uuid; pay uuid; ra uuid; hdr jsonb; BEGIN
IF auth.uid() IS DISTINCT FROM '10000000-0000-4000-a000-000000000001'::uuid THEN RAISE EXCEPTION 'Forbidden'; END IF;
INSERT INTO companies(id,nome,is_client) VALUES(client,'[DISPOSABLE EXPENSE FIXTURE] client',true); INSERT INTO pm_projects(id,name,status,company_id) VALUES(p,'[DISPOSABLE EXPENSE FIXTURE] project','active',client),(p2,'[DISPOSABLE EXPENSE FIXTURE] project2','active',client); INSERT INTO collaborators(id,nome,email) VALUES(c,'[DISPOSABLE EXPENSE FIXTURE] payer','pe-fixture@example.invalid'); INSERT INTO bank_accounts(id,account_name,entity_id) VALUES(bank,'[DISPOSABLE EXPENSE FIXTURE] bank','00000000-0000-4000-a000-000000000001');
r:=pe_action('save',jsonb_build_object('projectId',p,'description','[DISPOSABLE EXPENSE FIXTURE] GBP taxi','currency','GBP','originalAmount',100,'eurAmount','120','exchangeDate','2026-11-02','exchangeSource','fixture evidence','exchangeEvidence',jsonb_build_object('reference','fixture-fx'),'paidBy','personal','collaboratorId',c,'rebillMode','markup','markupPct',20,'taxTreatment','reinvoiced_cost','taxParameters',jsonb_build_object('vatRate',23),'intakeKey','fixture-completion-key')); e:=(r->>'id')::uuid;
IF (SELECT eur_amount FROM pm_expenses WHERE id=e)<>120 THEN RAISE EXCEPTION 'GBP evidence failed'; END IF;
r:=pe_action('save',jsonb_build_object('intakeKey','fixture-completion-key')); IF (r->>'id')::uuid<>e THEN RAISE EXCEPTION 'Idempotence failed'; END IF;
r:=pe_action('save',jsonb_build_object('expenseId',e,'description','[DISPOSABLE EXPENSE FIXTURE] edited GBP taxi','currency','GBP','originalAmount',100,'eurAmount',120,'exchangeDate','2026-11-02','exchangeSource','fixture evidence','exchangeEvidence',jsonb_build_object('reference','fixture-fx'),'paidBy','personal','collaboratorId',c,'rebillMode','markup','markupPct',20,'taxTreatment','reinvoiced_cost','taxParameters',jsonb_build_object('vatRate',23),'receiptPath','fixture/personal.jpg'));
IF (SELECT receipt_path FROM pm_expenses WHERE id=e)<>'fixture/personal.jpg' THEN RAISE EXCEPTION 'Existing personal receipt edit failed'; END IF;
IF EXISTS(SELECT 1 FROM finance_holder_reimbursements WHERE project_expense_id=e) THEN RAISE EXCEPTION 'Unapproved obligation'; END IF;
PERFORM pe_action('submit',jsonb_build_object('expenseId',e)); PERFORM pe_action('decide',jsonb_build_object('expenseId',e,'approve',false,'reason','fixture rejection')); IF (SELECT approval_state FROM pm_expenses WHERE id=e)<>'rejected' THEN RAISE EXCEPTION 'Rejection failed'; END IF;
PERFORM pe_action('submit',jsonb_build_object('expenseId',e)); PERFORM pe_action('decide',jsonb_build_object('expenseId',e,'approve',true));
e2:=(pe_action('save',jsonb_build_object('projectId',p2,'description','[DISPOSABLE EXPENSE FIXTURE] meal','currency','EUR','originalAmount',30,'paidBy','personal','collaboratorId',c,'rebillMode','cost'))->>'id')::uuid; PERFORM pe_action('submit',jsonb_build_object('expenseId',e2)); PERFORM pe_action('decide',jsonb_build_object('expenseId',e2,'approve',true));
b:=(pe_action('batch',jsonb_build_object('collaboratorId',c,'obligationIds',(SELECT jsonb_agg(id) FROM finance_holder_reimbursements WHERE project_expense_id IN(e,e2))))->>'id')::uuid;
IF (SELECT sum(reserved_amount) FROM project_reimbursement_allocations WHERE batch_id=b)<>150 THEN RAISE EXCEPTION 'Cross-project batch wrong'; END IF;
INSERT INTO bank_transactions(bank_account_id,entity_id,transaction_date,description,amount,row_checksum) VALUES(bank,'00000000-0000-4000-a000-000000000001','2026-11-02','[DISPOSABLE EXPENSE FIXTURE] transfer',-75,gen_random_uuid()::text) RETURNING id INTO tx;
PERFORM pe_action('settleBatch',jsonb_build_object('batchId',b,'transactionId',tx,'amount',75)); IF fin_tx_open_balance(tx)<>0 THEN RAISE EXCEPTION 'Partial settlement failed'; END IF;
FOR ra IN SELECT id FROM project_reimbursement_allocations WHERE batch_id=b AND bank_transaction_id=tx LOOP PERFORM pe_action('reverseReimbursement',jsonb_build_object('allocationId',ra,'reason','fixture undo')); END LOOP; IF fin_tx_open_balance(tx)<>75 THEN RAISE EXCEPTION 'Undo failed'; END IF;
hdr:=jsonb_build_object('doc_type','client_invoice','status','issued','issue_date','2026-11-02','document_number','FT FIXTURE/91001','series','FIXTURE','counterparty_client_id',client,'project_id',p);
inv:=pe_invoice_from_expenses(hdr,jsonb_build_array(jsonb_build_object('expense_id',e,'expense_cost',120,'sort_order',0))); SELECT id INTO ia FROM project_expense_invoice_allocations WHERE expense_id=e;
IF (SELECT billed_amount FROM project_expense_invoice_allocations WHERE id=ia)<>144 OR (SELECT vat_amount FROM project_expense_invoice_allocations WHERE id=ia)<>33.12 THEN RAISE EXCEPTION 'Markup/VAT wrong'; END IF;
INSERT INTO financial_document_payments(document_id,amount,payment_date,method,created_by) VALUES(inv,88.56,'2026-11-02','bank_transfer',auth.uid()) RETURNING id INTO pay; PERFORM pe_action('receipt',jsonb_build_object('allocationId',ia,'paymentId',pay,'amount',88.56)); IF (SELECT received_net_amount FROM pe_expense_settlement_figures(p) WHERE expense_id=e)<>72 THEN RAISE EXCEPTION 'Net receipt wrong'; END IF;
cr:=pe_invoice_from_expenses(hdr||jsonb_build_object('doc_type','client_credit_note','document_number','NC FIXTURE/91002','original_document_id',inv),jsonb_build_array(jsonb_build_object('credit_allocation_id',ia,'expense_cost',30,'sort_order',0))); IF (SELECT credited_cost FROM pe_expense_settlement_figures(p) WHERE expense_id=e)<>30 THEN RAISE EXCEPTION 'Partial credit wrong'; END IF;
BEGIN PERFORM pe_action('receipt',jsonb_build_object('allocationId',ia,'paymentId',pay,'amount',88.56)); RAISE EXCEPTION 'Duplicate receipt admitted'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='Duplicate receipt admitted' THEN RAISE; END IF; END;
BEGIN INSERT INTO pm_expenses(project_id,description,purchase_price) VALUES(p,'legacy bypass',1); RAISE EXCEPTION 'Legacy insert admitted'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='Legacy insert admitted' THEN RAISE; END IF; END;
RAISE NOTICE 'PASS: GBP evidence, idempotence, approval/rejection/reapproval, cross-project batch, partial settlement/undo, invoice/markup/VAT, net receipt, partial credit, duplicate refusal, legacy insert refusal';
SELECT id INTO ra FROM project_expense_receipt_allocations WHERE invoice_allocation_id=ia AND reversed_at IS NULL;
PERFORM pe_action('reverseReceipt',jsonb_build_object('allocationId',ra,'reason','fixture undo'));
PERFORM pe_action('reverseInvoice',jsonb_build_object('allocationId',ia,'reason','fixture undo'));
IF NOT EXISTS(SELECT 1 FROM project_expense_invoice_allocations WHERE id=ia AND reversed_at IS NOT NULL) THEN RAISE EXCEPTION 'Invoice reversal failed'; END IF;
RAISE NOTICE 'PASS: all ten pe_action branches, personal existing save/edit/attached receipt'; END $$;

BEGIN; SELECT set_config('request.jwt.claim.sub','10000000-0000-4000-a000-000000000001',true); SELECT public.test_pe_branches(); ROLLBACK;
